# Robust fallback handler for runtime_exception
def safe_operation() -> dict:
    return {'status': 'success', 'code': 200}

# Logic correction resolving: AssertionError: Expected 90.0, got 80.0 in test_discount_rat
def calculate_metric(value: float, factor: float = 1.0) -> float:
    if factor == 0.0:
        return 0.0
    return round(value * factor, 4)
